document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('#redo'):$('#undo')).click();}else if(e.code==='Space'){e.preventDefault();$('#play').click();}else if(!e.ctrlKey&&!e.metaKey){const t={b:'brush',p:'pencil',e:'erase'}[e.key.toLowerCase()];if(t)selectTool(t);}});
