async function imageFromUrl(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('图片无法解码，请尝试 PNG 或 JPG'));img.src=src;});}
async function setReference(src,name){
 const img=await imageFromUrl(src);if(img.width*img.height>16000000)throw Error('参考图最多 1600 万像素');
 const original=document.createElement('canvas');original.width=img.width;original.height=img.height;original.getContext('2d').drawImage(img,0,0);
 const c=document.createElement('canvas');c.width=engine.doc.width;c.height=engine.doc.height;const x=c.getContext('2d'),scale=Math.min(c.width/img.width,c.height/img.height),ox=(c.width-img.width*scale)/2,oy=(c.height-img.height*scale)/2;x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(img,ox,oy,img.width*scale,img.height*scale);
 reference={original,canvas:c,rawCanvas:original,placement:[ox,oy,scale],sourceDataUrl:original.toDataURL('image/png'),dataUrl:c.toDataURL('image/png'),lineCanvas:null,name};$('#reference-preview').src=reference.dataUrl;$('#reference-overlay').src=reference.dataUrl;$('#reference-name').textContent=name;$('#reference-card').hidden=false;$('#reference-toggle').disabled=false;$('#extract-status').textContent='尚未提取';$('#dropzone').querySelector('strong').textContent='更换参考图';scheduleSave();record(`载入原始参考图：${name} · ${img.width} × ${img.height}`);
}
async function prepareReference(){if(!reference)throw Error('请先载入参考图');const current=reference;$('#extract-status').textContent='正在提取观察用线稿…';const lines=await extractReferenceLines(current.original);if(current!==reference)throw Error('参考已更换，请重新提取');reference.lineCanvas=lines;$('#extract-status').textContent='已提取 · 仅供观察，可能包含阴影伪边';record('完成参考线稿提取；画布未改变');return {prepared:true,method:'local-contrast-and-luminance-edges',width:lines.width,height:lines.height,canvasChanged:false};}

async function resourceDataUrl(path){const embedded=globalThis.EMBEDDED_REFERENCE_CARD_IMAGES?.[path];if(embedded)return embedded;const response=await fetch(path);if(!response.ok)throw Error('参考卡图片读取失败：'+path);const blob=await response.blob();return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error||Error('参考卡图片转换失败'));reader.readAsDataURL(blob);});}
async function loadReferenceCard({id}={}){const card=drawingReferenceCard(id),images=await Promise.all(card.images.map(async(image,index)=>({...image,index,dataUrl:await resourceDataUrl(image.publicPath)})));referenceCardReads.set(card.id,card.sha256);record(`完整读取人体参考卡：${card.id}《${card.title}》· ${images.length} 张图片`);return {...card,images,totalImages:images.length,complete:true,referenceKnowledge:referenceKnowledgeStatus()};}

async function loadFile(f){if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('请上传 PNG、JPG 或 WebP 图片');if(f.size>12*1024*1024)throw Error('图片不能超过 12 MB');const u=URL.createObjectURL(f);try{await setReference(u,f.name);}finally{URL.revokeObjectURL(u);}}
function clearReference(){reference=null;$('#reference-card').hidden=true;$('#reference-overlay').hidden=true;$('#reference-overlay').removeAttribute('src');$('#reference-preview').removeAttribute('src');$('#reference-toggle').disabled=true;$('#reference-toggle').setAttribute('aria-pressed','false');$('#share-reference').checked=false;$('#reference-file').value='';$('#dropzone').querySelector('strong').textContent='选择或拖入参考图';}
$('#reference-file').onchange=safe(e=>loadFile(e.target.files[0]));$('#dropzone').ondragover=e=>{e.preventDefault();$('#dropzone').classList.add('dragging');};$('#dropzone').ondragleave=()=>$('#dropzone').classList.remove('dragging');$('#dropzone').ondrop=e=>{e.preventDefault();$('#dropzone').classList.remove('dragging');safe(()=>loadFile(e.dataTransfer.files[0]))();};$('#remove-reference').onclick=()=>{clearReference();scheduleSave();};$('#reference-toggle').onclick=()=>{if(!reference)return;$('#reference-overlay').hidden=!$('#reference-overlay').hidden;$('#reference-toggle').setAttribute('aria-pressed',String(!$('#reference-overlay').hidden));};$('#reference-opacity').oninput=e=>{$('#reference-overlay').style.opacity=Number(e.target.value)/100;$('#reference-opacity-value').textContent=e.target.value+'%';};
