async function submitPayload(payload){const p=Array.isArray(payload)?{commands:payload}:payload;if(!p||!Array.isArray(p.commands))throw Error('需要包含 commands 数组的 JSON');if(p.animate!==undefined&&typeof p.animate!=='boolean')throw Error('animate 必须为布尔值');assertBatchLimit(p.commands.length);assertRequiredReferenceCards();assertDrawingCycle('submit');const result=await engine.submit(p.commands,{animate:p.animate??true,layer:activeLayer,stage:activeStage});kind='笔迹指令绘画';$('#doc-kind').textContent=kind;record(`提交 ${p.commands.length} 笔${p.animate===false?' · 立即绘制':' · 逐笔播放'}`);scheduleSave();return {accepted:result.accepted,commandIds:result.commandIds,totalCommands:result.commands,progress:result.progress,playing:result.playing};}
$('#command-form').onsubmit=async e=>{e.preventDefault();const out=$('#command-result');try{const parsed=JSON.parse($('#commands').value);const p=Array.isArray(parsed)?{commands:parsed}:parsed;const methods={new_document:'newDocument',set_plan:'setPlan',revise:'revise',set_layers:'setLayers',scan_gaps:'scanGaps',preview_leak:'previewLeak',edit_pressure:'editPressure',smooth_strokes:'smoothStrokes',clear_diagnostics:'clearDiagnostics',set_scene:'setScene',set_phase:'setPhase',edit_geometry:'editGeometry',checkpoint:'checkpoint',record_inspection:'recordInspection',record_review:'recordReview',prepare_review:'prepareReview',observe_review:'observeReview',update_issue:'updateIssue',playback:'playback',undo:'undo'};const method=p.action?methods[p.action]:null;if(p.action&&!method)throw Error('不支持的指令 action');const result=method?await api[method](p.options||{}):await api.submit({...p,animate:$('#animate-submit').checked});out.className='result';out.textContent=result.accepted!==undefined?`已接收 ${result.accepted} 笔；可在时间轴查看过程。`:`已完成 ${p.action}；当前 ${result.commands??engine.doc.commands.length} 笔。`;}catch(err){out.className='result error';out.textContent=err.message;}};
