  revise:async options=>{assertBatchLimit(revisionStrokeCount(options),'返修');assertRequiredReferenceCards();assertDrawingCycle('revise');const result=engine.revise(options);scheduleSave();record(`局部改线：${result.changed} 笔 · ${options.note||'笔迹修改'}`);return result;},
  setLayers:async({layers})=>{engine.setLayers(layers);scheduleSave();return {layers:engine.state().layers,metrics:engine.metrics};},
  recordInspection:async options=>{const r=reviewEvidence.recordInspection(options);scheduleSave();return r;},
  recordReview:async options=>{const r=reviewEvidence.record(options);scheduleSave();record(r.note);return r;},
  getScene:async()=>({...structuredClone(engine.doc.scene),issues:sceneIssues(engine.doc)}),
  checkConnections:async options=>checkConnections(engine.doc,{...options,layerIds:engine.doc.layers.filter(l=>engine.layerVisible(l)).map(l=>l.id)}),
  setScene:async options=>{const r=engine.setScene(options);scheduleSave();record(options.note||'更新对象空间');return r;},
  setPhase:async options=>{const r=engine.setPhase(options);resetReferenceKnowledge();scheduleSave();return {...r,drawingProtocol:drawingProtocol({phase:r.phase}),referenceKnowledge:referenceKnowledgeStatus()};},
  editGeometry:async options=>{assertDrawingCycle('revise');const r=engine.editGeometry(options);scheduleSave();record(options.note);return r;},
  previewRevision:async options=>engine.previewRevision(options),
